"""Write MATRIX.md from results/*.json.  python benchmarks/memory-systems/summarize.py"""
import glob
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ORDER = ["dict", "mem0", "langgraph"]


def main():
    res = {json.load(open(p))["backend"]: json.load(open(p)) for p in glob.glob(os.path.join(HERE, "results", "*.json"))}
    lines = ["# Memory-systems matrix", "",
             "Generated by `summarize.py`. Each cell: the findings AgentSec reported for that scenario, or `-` for none. "
             "Same deterministic agent and scenarios for every backend; only the memory library and the agent's memory "
             "configuration differ (see memory_agent.py).", ""]
    for b in [x for x in ORDER if x in res]:
        d = res[b]
        ver = ", ".join("%s %s" % kv for kv in sorted(d["versions"].items())) or "no library"
        lines += ["## %s (%s)" % (d["backend_label"], ver), ""]
        cfgs = list(d["configs"])
        sids = list(d["configs"][cfgs[0]]["scenarios"])
        lines.append("| Scenario | " + " | ".join(cfgs) + " |")
        lines.append("|---|" + "---|" * len(cfgs))
        for sid in sids:
            cells = [", ".join(d["configs"][c]["scenarios"][sid]["rules"]) or "-" for c in cfgs]
            lines.append("| `%s` | %s |" % (sid, " | ".join(cells)))
        lines.append("")
    with open(os.path.join(HERE, "MATRIX.md"), "w") as fh:
        fh.write("\n".join(lines) + "\n")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
